function lenisInit(){

    const lenis = new Lenis({
        duration: 1.2,
        easing: (t) => (t === 1 ? 1 : 1 - Math.pow(2, -10 * t)),
        direction: "vertical",
        gestureDirection: "vertical",
        smooth: true,
        smoothTouch: false,
        touchMultiplier: 2,
    });


    lenis.on('scroll', (e) => {
        var dir = e.direction;
        var scroll = e.scroll;
        if(dir==1) { //scroll down
            $('body').removeClass("menuOpen");
            if(scroll > 100){
                $('body').addClass("scrolling");
            }
        } else{
            //scroll up
            if(scroll < 100){
                $('body').removeClass("scrolling"); 
            } 
        }
    })


    function raf(time) {
        lenis.raf(time)
        requestAnimationFrame(raf)
    }

    requestAnimationFrame(raf)

    window.lenis = lenis;
}


