<?php

namespace AtrioTeam\Lintilla\Http\Middleware;

use Closure;
use Illuminate\Support\Facades\Request;
use Illuminate\Support\Facades\Route;

/**
 * Redirect to user agent locale, only for "/" route
 */
class RootRedirectLocale
{
    public function handle($request, Closure $next)
    {

        if ($request->getRequestUri() != '/') {
            return $next($request);
        }

        $availableLocales = array_keys(config('lintilla.locales'));

        // redirect da user agent se sono in root
        $uric = parse_url($request->getRequestUri());
        $redirectLocale = null;
        $qst = !empty($uric["query"]) ? $uric["query"] : '';
        $qst = $qst ? '?'.$qst : '';

        $userLangs = preg_split('/,|;/', $request->getPreferredLanguage());
        foreach ($userLangs as $userLocale) {
            if (in_array($userLocale, $availableLocales)) {
                $redirectLocale = $userLocale;
            }
        }

        $redirectLocale = $redirectLocale ?? current($availableLocales);

        if ($redirectLocale) {
            $redirectUrl = '/'.$redirectLocale.$qst;

            $checkRequest = Request::create($redirectUrl);

            // se un url corrispondente esiste, reindirizza
            try {
                $route = Route::getRoutes()->match($checkRequest);

                // v. sotto per evitare route di fallback
                if ($route->uri() != '{fallbackPlaceholder}') {
                    return redirect($route->uri(), 302);
                }


            } catch (\Symfony\Component\HttpKernel\Exception\NotFoundHttpException $e) {
                // la route non esiste, non faccio nulla
            }

        }

        // no redirect happened, continue
        return $next($request);

    }
}

