namespace AtrioTeam\Lintilla\Http\Middleware;

use AtrioTeam\Lintilla\Localization\LangManager;
use Closure;

/**
 * Imposta localizzazione
 */
class SetLocale
{
    public function handle($request, Closure $next)
    {

        $availableLocales = array_keys(app(LangManager::class)->getLocales());

        // lcoale da cartella url
        $locale = app(LangManager::class)->setLocale(request()->getRequestUri());

        // locale da parametro query stringa (alcuni link potrebbero contenerla, es. link di password reset)
        if ($request->locale && in_array($request->locale, $availableLocales)) {
            $locale = $request->locale;
        }

        // recupero da sessione
        if (! $locale && session()->has('locale')) {
            $locale = session('locale');
        }

        // se non ne ho ancora uno valido, prendo quello di default
        if (!$locale) {
            $locale = current($availableLocales);
        }
        session()->put('locale', $locale);

        /**
         * imposto locale
         */
        app()->setLocale($locale);
        app(LangManager::class)->store(app()->getLocale());


        /**
         * Inietto traduzioni da csv nel translator di laravel
         */
        app(LangManager::class)->loadTrads(app()->getLocale());


        /**
         * carico link
         */

        return $next($request);


    }
}

