namespace AtrioTeam\Lintilla\Http\Middleware;

use AtrioTeam\Lintilla\Http\Exceptions\ComingSoonException;
use AtrioTeam\Lintilla\Http\Exceptions\MaintenanceException;
use Closure;
use Illuminate\Foundation\Http\Middleware\CheckForMaintenanceMode as DefaultMiddleware;
use Illuminate\Support\Facades\Cookie;

class CustomMaintenanceMode extends DefaultMiddleware
{
    /**
     * Handle an incoming request.
     *
     * @param  \Closure(\Illuminate\Http\Request): (\Symfony\Component\HttpFoundation\Response)  $next
     */
    public function handle($request, Closure $next)
    {

        // priority to default framework maintenance mode
        if ($this->app->maintenanceMode()->active()) {
            return parent::handle($request, $next);
        }

        // ?p=1 per abilitare visualizzazione
        if ($request->p == 1) {
            Cookie::queue("lintilla_preview", 1);
            return $next($request);
        }

        if (config('lintilla.app_down') == 'maintenance' &&
            (int)Cookie::get("lintilla_preview") !== 1
        ):
            throw new MaintenanceException();
        endif;

        if (config('lintilla.app_down') == 'comingsoon' &&
            (int)Cookie::get("lintilla_preview") !== 1
        ):
            throw new ComingSoonException();
        endif;

        return $next($request);
    }
}

