<?php

namespace AtrioTeam\Lintilla\Localization;

use Exception;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Route;
use InvalidArgumentException;

/**
 * Carica i link in lingua nel router di Laravel.
 */
class Router
{
    protected $locale;

    protected $csvPath;

    protected $links;

    protected $routes = null;

    protected string $langSource;

    /**
     * @var array<string,string> $locales
     */
    protected array $locales;

    public function __construct($locales = [], string $langSource = 'file')
    {
        $this->locales = $locales;

        $this->langSource = $langSource;

        if (!in_array($langSource, ['file', 'database'])) {
            throw new InvalidArgumentException("Invalid lang source");
        }
    }


    /**
     * Caricamento specifico (pensato per essere eventualmente esteso)
     */
    protected function loadProvider()
    {
        $links = [];

        /**
         * caricamento da db
         */
        if ($this->langSource === "database") {
            // ordino i link per priorità crescente, per far sì che le route con priorità più alta vengano registrate
            // dopo e sovrascrivano un'eventuale route con la stessa uri (in questo caso infatti
            // nel router di laravel prevale la seconda route registrata)
            $linksTemp = DB::table("lang_link")->orderBy("priority", "asc")->select()->get();
            foreach ($linksTemp as $key => $value) {
                $link = (array) $value;
                $links[] = $link;
            }
        }


        /**
         * caricamento da csv
         */
        $sourceFile = lang_path("vendor/lintilla/links.json");
        if ($this->langSource === "file" && file_exists($sourceFile)) {
            $links = json_decode(file_get_contents($sourceFile), true);

            // per l'ordinamento, vedi nota sopra per recupero da db
            $links = collect($links)->sortBy("priority");
        }


        return $links;
    }



    /**
     * legge le route per caricarle nel router di laravel
     */
    protected function load()
    {
        $links = $this->loadProvider();

        $this->routes = [];

        if ($this->locales) {
            foreach ($this->locales as $locale => $label) {
                foreach ($links as $key => $value) {
                    // non registro i valori vuoti
                    if (!strlen($value["link_".$locale])) {
                        continue;
                    }

                    $isAbsolute = strpos($value["link_".$locale], 'http') === 0;

                    $link = $isAbsolute ? $value["link_".$locale] : '/'.$locale.rtrim($value["link_".$locale], '/');

                    $code = $value["code"].'_'.$locale;

                    $link = [
                        "code" => $code,
                        "type" => $value["type"],
                        "link" => $link,
                        "handler" => $value["filename"],
                    ];

                    $this->routes[$code] = $link;
                }
            }
        } else {
            foreach ($links as $key => $value) {
                $link = $value["link"];

                $code = $value["code"];

                $this->routes[$code] = [
                    "code" => $code,
                    "type" => $value["type"],
                    "link" => $link,
                    "handler" => $value["filename"],
                ];
            }
        }

        return $this;
    }


    /**
     * registra le route assegnatele nel router di laravel
     */
    public function register()
    {
        if ($this->routes === null) {
            $this->load();
        }

        foreach ($this->routes as $code => $values) {
            // da allineare al locale
            $link = $values["link"];

            // trasformo in maiuscolo e in array valido per router
            $values["type"] = strtoupper($values["type"]);
            $values["type"] = explode(",", $values["type"]);

            /**
             * Handler vuoto o script
             */
            if (!strlen($values["handler"]) || pathinfo($values["handler"], PATHINFO_EXTENSION) == 'php') {
                $handler = $values["handler"];

                Route::addRoute($values["type"], $link, function () use ($handler, $code) {
                    // recupero query stringa e l'aggiungo a $_GET
                    $cps = parse_url($handler);

                    $params = array();

                    // aggiungo i parametri alla richiesta
                    if (isset($cps["query"])) {
                        parse_str($cps["query"], $params);
                        request()->request->add($params);
                    }

                    // recupero il nome della view
                    $viewName = str_replace(".blade.php", "", $handler);

                    if (!view()->exists($viewName)) {
                        throw new Exception("La view non esiste, verifica di aver impostato un controller / file per il link.");
                    }

                    return view($viewName);
                })->name($code)->middleware("web");
            } else {

                $handler = $values['handler'];

                // se inizia con "\" assumo che sia un namespace assoluto e quindi lo lascio così com'è
                // TODO: refactoring
                // es. \App\Namespace\Controller
                if (strpos($handler, '\\') === 0) {

                    // costruisco namespace completo se non è già assoluto(assumo App\Http\Controllers)
                } elseif (strpos($handler, 'App\Http\Livewire') === false && strpos($handler, 'App\Http\Controllers') === false) {
                    $handler = 'App\Http\Controllers\\'.$handler;
                }

                Route::addRoute($values["type"], $link, $handler)->name($code)->middleware("web");

            }
        } // ciclo link
    }


    /**
     * Restituisce tutti i link alternativi.
     *
     * @param string searchCode codice della route per cui si vogliono gli alternate
     */
    public function getAllAlternates($searchCode = null)
    {
        if ($this->routes === null) {
            $this->load();
        }

        $alternates = [];

        // recupero la route interessata
        if (!array_key_exists($searchCode.'_'.app()->getLocale(), $this->routes)) {
            //throw new Exception("Route non esistente per generazione degli alternate [$searchCode]");
            return $alternates;
        }

        // per ciascun locale recupero il link equivalente
        foreach (app(LangManager::class)->getLocales() as $kLocale => $locale) {
            // se non esiste il link in questa lingua, salto
            if (!array_key_exists($searchCode.'_'.$kLocale, $this->routes)) {
                continue;
            }
            $alternates[$kLocale] = $this->routes[$searchCode.'_'.$kLocale]["link"];
        }

        return $alternates;
    }


    /**
     * Restituisce una route
     */
    public function getRoute($name)
    {
        return $this->routes && array_key_exists($name, $this->routes) ? $this->routes[$name]["link"] : null;
    }
}

