/**
 * jQuery
 */
import jQuery from 'jquery';
Object.assign(window, { $: jQuery, jQuery });

/**
 * Barba.js
 */
import barba from '@barba/core';
window.barba = barba;

/**
 * UIkit
 */
import UIkit from 'uikit/dist/js/uikit-core';
import 'uikit/dist/css/uikit.min.css';
window.UIkit = UIkit;

/**
 * DOM ready
 */
$(function () {

    /**
     * Configurazione globale componenti uikit
     */
    (function () {
        // container false per modal, evita duplicazione elemento in seguito a caricamenti asincroni (barba.js)
        UIkit.mixin({
            data: {
                container: false,
            },
        }, 'modal');
    })();

    /**
     * Init di barba
     * Deve essere incluso nella blade base!
     */
    barbaInit();

    /**
     * Update necessari dopo caricamenti livewire
     */
    Livewire.hook('message.processed', function () {
        // scroll a eventuale messaggio di errore form
        scrollToFormError();
    });

    // scroll a eventuale messaggio di errore form, al caricamento!
    scrollToFormError();

});

/**
 * Scroll al primo messaggio di errore di un form
 */
function scrollToFormError() {
    // se ho dei messaggi di validazione di un form, scrollo al primo messaggio
    if (!$('form .field__error').length) {
        return;
    }
}

/**
 * Funzione di uscita pagina
 */
function pageExit(callback) {
    // porto in primo piano prima di iniziare animazione
    $('#page_loader').css({
        zIndex: 49, // sotto all'header!
    });

    // animazione in uscita dalla pagina (il loader entra)
    $('#page_loader').animate({ top: 0 }, 500, function () {
        // Animation complete
        if (callback && typeof callback === 'function') {
            callback();
        }
    });
}

/**
 * Funzione di entrata pagina
 */
function pageEnter(callback) {
    // animazione in entrata della pagina (uscita del loader)
    $('#page_loader').animate({ opacity: '0' }, 1000, function () {
        // Animation complete

        // anchor link
        document.querySelectorAll('a[href^="#"].anchor').forEach(function (anchor) {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();
                document.querySelector(this.getAttribute('href'))?.scrollIntoView({ behavior: 'smooth' });
            });
        });

        // porto sotto per poter interagire con pagina
        $('#page_loader').css({
            zIndex: -1,
            top: '100vh',
            opacity: 1,
        });
        if (callback && typeof callback === 'function') {
            callback();
        }
    });
}

/**
 * Gestione caricamento asincrono
 */
function barbaInit() {

    // controllo disponibilità barba
    if (typeof barba === 'undefined') {
        return console.log('barba non disponibile');
    }

    barba.init({
        debug: window.ENV === 'local',
        logLevel: window.ENV === 'local' ? 'debug' : 'error',
        transitions: [{
            name: 'default-transition',
            beforeLeave(data) {
                // attendi finchè loader entra prima di lasciare la pagina
                const done = this.async();
                return pageExit(function () {
                    return done();
                });
            },
            afterEnter(data) {
                // tracciamento analytics
                if (typeof gtag === 'function' && typeof GA_MEASUREMENT_ID !== 'undefined') {
                    gtag('config', GA_MEASUREMENT_ID, { page_path: window.location.pathname });
                }

                updateDom(data, function () {
                    pageEnter();

                    // rebind degli eventi livewire sui nuovi contenuti caricati
                    if (window.livewire) {
                        window.livewire.rescan();
                    }
                });
            },
        }],
        requestError: (trigger, action, url, response) => {
            // forzo a seguire le url 404 per visione del messaggio
            if (action === 'click' && response.status === 404) {
                window.location.href = url;
                return false;
            }
            console.log(trigger, action, url, response);
        },
        preventRunning: true,
    });
}

/**
 * Aggiorna il dom dopo una transizione barba.
 * NB: i selettori di menu/footer sono placeholder, da allineare
 * quando verrà costruito il layout pubblico definitivo.
 */
function updateDom(data, callback) {

    var html = data.next.html;
    var newHeadHtml = html.match(/<head[\s\S]*?>[\s\S]*?<\/head>/gi)[0];

    // true mantiene gli script
    var $newPageHead = $.parseHTML(newHeadHtml, document, true);

    /**
     * Aggiorno namespace di body
     */
    $('body').attr('data-namespace', data.next.namespace);

    /**
     * Aggiorno elemento attivo menu principale
     */
    $('#page_header-mainmenu .uk-active').removeClass('uk-active');
    $('#page_header-mainmenu [data-namespace="' + data.next.namespace + '"]').addClass('uk-active');

    /**
     * aggiorno html altri elementi
     * In ogni elemento dell'array inserire:
     * - o il selettore completo
     * - o il selettore + l'attributo che si vuole rimpiazzare
     */
    [
        'head',
        '#page_header-mainmenu',
        ['#page_header .logo a', 'href'],
        '#page_footer .info_menu',
    ].forEach(function (selector) {

        let realSelector = Array.isArray(selector) ? selector[0] : selector;
        let attribute = Array.isArray(selector) ? selector[1] : null;

        // recupero elemento nel nuovo html in arrivo
        let el = $(realSelector, $(data.next.html));

        // no lambda qui!
        $(realSelector).each(function () {
            if (attribute !== null) {
                // rimpiazzo attributo
                $(this).attr(attribute, el.attr(attribute));
            } else {
                // rimpiazzo contenuto html nella pagina
                $(this).html(el.html());
            }
        });

    });

    /**
     * aggiornamento di script specifici nell'head
     */
    $newPageHead = $('<head />').html($newPageHead);
    var headTags = [
        "meta[name='keywords']",
        "meta[name='description']",
        "meta[property^='og']",
        "meta[name^='twitter']",
        'meta[itemprop]',
        'link[itemprop]',
        "link[rel='prev']",
        "link[rel='next']",
        "link[rel='canonical']",
        "link[rel='alternate']",
    ].join(',');

    $('head').find(headTags).remove();
    $newPageHead.find(headTags).appendTo('head');

    /**
     * Caricamento degli script presenti nel container della nuova pagina
     */
    $(data.next.container).find('script').each(function (i, script) {
        var $script = $(script);

        if ($script.attr('src')) {
            $.getScript($script.attr('src'));
        } else {
            $script.appendTo('[data-barba="container"]');
        }
    });

    if (callback && typeof callback === 'function') {
        return callback();
    }

    return true;
}

